/* Swaystone — the page wears the desktop's palettes.
 *
 * Every card previews its own theme using local custom properties, and picking
 * one writes that palette onto :root, which is the only place the stylesheet
 * reads colours from. That is the same trick the desktop plays: one palette,
 * defined once, and every consumer holds a rendered copy.
 *
 * Palette data comes from themes.js, generated by tools/site-themes.py.
 */
(function () {
  "use strict";

  var data = window.SWAYSTONE;
  var grid = document.getElementById("theme-grid");
  if (!data || !grid) return;

  var ROLES = [
    "bg", "bar", "surface", "surface_alt", "text", "muted",
    "accent", "secondary", "tertiary", "ok", "warning", "urgent"
  ];

  var STORE = "swaystone-theme";
  var themes = data.themes;
  var current = data.default;

  /* localStorage is a nicety, not a requirement: a private window or a browser
     set to block site data throws on access rather than returning null. */
  function remembered() {
    try { return localStorage.getItem(STORE); } catch (e) { return null; }
  }
  function remember(name) {
    try { localStorage.setItem(STORE, name); } catch (e) { /* fine */ }
  }

  function byName(name) {
    for (var i = 0; i < themes.length; i++) {
      if (themes[i].name === name) return themes[i];
    }
    return null;
  }

  function apply(theme) {
    var root = document.documentElement;
    for (var i = 0; i < ROLES.length; i++) {
      var role = ROLES[i];
      /* the stylesheet spells surface_alt with a hyphen, as CSS does */
      root.style.setProperty("--" + role.replace("_", "-"), theme[role]);
    }
    root.setAttribute("data-theme", theme.name);
    root.style.colorScheme = theme.mode === "light" ? "light" : "dark";
    current = theme.name;

    var buttons = grid.querySelectorAll(".theme-btn");
    for (var j = 0; j < buttons.length; j++) {
      var on = buttons[j].dataset.theme === theme.name;
      buttons[j].setAttribute("aria-checked", on ? "true" : "false");
      buttons[j].tabIndex = on ? 0 : -1;
      var tag = buttons[j].querySelector(".theme-current");
      if (tag) tag.textContent = on ? "in use" : "";
    }
  }

  function card(theme) {
    var b = document.createElement("button");
    b.type = "button";
    b.className = "theme-btn";
    b.dataset.theme = theme.name;
    b.setAttribute("role", "radio");
    b.setAttribute("aria-checked", "false");
    b.tabIndex = -1;

    /* local tokens so the card shows its own palette, not the page's */
    b.style.setProperty("--tbg", theme.bg);
    b.style.setProperty("--ttext", theme.text);
    b.style.setProperty("--tmuted", theme.muted);
    b.style.setProperty("--taccent", theme.accent);

    var bar = document.createElement("div");
    bar.className = "swatch-bar";
    ["accent", "secondary", "tertiary", "ok", "warning", "urgent"].forEach(function (role) {
      var s = document.createElement("span");
      s.style.background = theme[role];
      bar.appendChild(s);
    });

    var meta = document.createElement("div");
    meta.className = "theme-meta";

    var nameRow = document.createElement("div");
    nameRow.className = "theme-name";
    var nm = document.createElement("span");
    nm.textContent = theme.name;
    var mode = document.createElement("span");
    mode.className = "theme-mode";
    mode.textContent = theme.mode;
    nameRow.appendChild(nm);
    nameRow.appendChild(mode);

    var desc = document.createElement("p");
    desc.className = "theme-desc";
    desc.textContent = theme.description;

    var tag = document.createElement("span");
    tag.className = "theme-current";

    meta.appendChild(nameRow);
    meta.appendChild(desc);
    meta.appendChild(tag);

    b.appendChild(bar);
    b.appendChild(meta);

    b.addEventListener("click", function () {
      apply(theme);
      remember(theme.name);
    });

    return b;
  }

  themes.forEach(function (t) { grid.appendChild(card(t)); });

  /* arrow keys walk the group, as a radiogroup should */
  grid.addEventListener("keydown", function (ev) {
    var keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp"];
    if (keys.indexOf(ev.key) === -1) return;
    ev.preventDefault();
    var step = (ev.key === "ArrowRight" || ev.key === "ArrowDown") ? 1 : -1;
    var idx = 0;
    for (var i = 0; i < themes.length; i++) {
      if (themes[i].name === current) { idx = i; break; }
    }
    var next = themes[(idx + step + themes.length) % themes.length];
    apply(next);
    remember(next.name);
    grid.querySelector('[data-theme="' + next.name + '"]').focus();
  });

  apply(byName(remembered()) || byName(data.default) || themes[0]);
})();
